#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
using namespace std;

int removeDuplicates(vector<int>& nums) {
    if (nums.empty()) return 0;
    int k = 0;
    for (int i = 1; i < nums.size(); i++) {
        if (nums[i] != nums[k]) {
            k++;
            nums[k] = nums[i];
        }
    }
    return k + 1;
}

int main() {
    string line;
    if (getline(cin, line)) {
        if (line.front() == '[') line = line.substr(1, line.size() - 2);
        stringstream ss(line);
        vector<int> nums;
        string val;
        while (getline(ss, val, ',')) {
            nums.push_back(stoi(val));
        }
        cout << removeDuplicates(nums) << endl;
    }
    return 0;
}

