#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int removeDuplicates(int* nums, int numsSize) {
    if (numsSize == 0) return 0;
    int k = 0;
    for (int i = 1; i < numsSize; i++) {
        if (nums[i] != nums[k]) {
            k++;
            nums[k] = nums[i];
        }
    }
    return k + 1;
}

int main() {
    char buffer[1000000];
    if (fgets(buffer, sizeof(buffer), stdin)) {
        char* p = buffer;
        while (*p && (*p == '[' || *p == ' ' || *p == '\n')) p++;
        int nums[30000], n = 0;
        char* token = strtok(p, ",] \n");
        while (token) {
            nums[n++] = atoi(token);
            token = strtok(NULL, ",] \n");
        }
        printf("%d\n", removeDuplicates(nums, n));
    }
    return 0;
}
